-- 表结构: posts
CREATE TABLE `posts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `author_id` int NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` enum('学习心得','问题求助','经验分享','其他') COLLATE utf8mb4_unicode_ci DEFAULT '其他',
  `privacy` enum('public','friends','private') COLLATE utf8mb4_unicode_ci DEFAULT 'public',
  `hashtags` json DEFAULT NULL,
  `images` json DEFAULT NULL,
  `videos` json DEFAULT NULL,
  `likes_count` int DEFAULT '0',
  `views` int DEFAULT '0',
  `is_deleted` tinyint(1) DEFAULT '0',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_author` (`author_id`),
  KEY `idx_category` (`category`),
  KEY `idx_created_at` (`created_at`),
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 表数据: posts
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (1,2,'今天学会了"你好"的手语表达','今天学会了"你好"的手语表达，感觉很有成就感！大家有什么学习技巧可以分享吗？#手语学习 #初学者','其他','public',NULL,NULL,NULL,1,32,0,Fri Mar 06 2026 22:02:24 GMT+0800 (GMT+08:00),Sun Mar 08 2026 11:09:36 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (2,10,'分享一个学习心得','分享一个学习心得：每天坚持练习15分钟，比一次性练习2小时效果更好。循序渐进很重要！#学习心得 #坚持','其他','public',NULL,NULL,NULL,1,41,0,Wed Mar 04 2026 22:02:24 GMT+0800 (GMT+08:00),Sun Mar 08 2026 15:54:48 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (3,11,'本周的挑战','本周的挑战：学会用手语表达"今天天气很好"。大家可以尝试一下，有问题随时提问！#挑战 #手语练习','其他','public',NULL,NULL,NULL,0,51,0,Fri Mar 06 2026 22:02:24 GMT+0800 (GMT+08:00),Sat Mar 07 2026 22:02:24 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (4,12,'手语和口语的区别','手语和口语最大的区别在于，手语是视觉语言，需要用到面部表情、身体姿态和手势。学习手语不仅是学习手势，还要学习 Deaf 文化。#聋人文化 #手语差异','其他','public',NULL,NULL,NULL,1,22,0,Wed Mar 04 2026 22:02:24 GMT+0800 (GMT+08:00),Sun Mar 08 2026 15:55:01 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (5,13,'推荐一个学习资源','推荐一个学习资源：YouTube上的"Sign Language 101"频道，讲解非常清晰，适合初学者！#学习资源 #推荐','其他','public',NULL,NULL,NULL,2,96,0,Sat Mar 07 2026 22:02:24 GMT+0800 (GMT+08:00),Sun Mar 15 2026 13:39:22 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (6,2,'第一次和聋人朋友交流','今天第一次用学到的手语和聋人朋友交流，虽然很简单，但对方很耐心地纠正我的手势，这种体验太棒了！#聋健交流 #实践','其他','public',NULL,NULL,NULL,1,76,0,Wed Mar 04 2026 22:02:24 GMT+0800 (GMT+08:00),Sun Mar 15 2026 14:03:54 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (7,10,'手语学习的难点','我觉得手语学习最大的难点是语法结构和口语完全不同，需要重新建立语言思维。大家有什么好的学习方法吗？#学习困难 #求助','其他','public',NULL,NULL,NULL,0,47,0,Wed Mar 04 2026 22:02:24 GMT+0800 (GMT+08:00),Sat Mar 07 2026 22:02:24 GMT+0800 (GMT+08:00));
INSERT INTO posts (id,author_id,title,content,category,privacy,hashtags,images,videos,likes_count,views,is_deleted,created_at,updated_at) VALUES (8,11,'庆祝学习一个月','庆祝自己坚持学习手语一个月！从完全不懂到现在能进行简单对话，感谢这个平台提供的AI翻译功能！#里程碑 #感谢','其他','public',NULL,NULL,NULL,0,27,0,Fri Mar 06 2026 22:02:24 GMT+0800 (GMT+08:00),Sat Mar 07 2026 22:02:24 GMT+0800 (GMT+08:00));
